(3494505, 487737, 66341, '<td valign="top">Nice composition, but really you needed a slower exposure to show the spin. Pick the highest aperture number and lowest ISO number possible. If on an instant camera, try setting to landscape mode. If really desperate, put one or more sunglasses in front of the lens</td>', 'Nice composition, but really you needed a slower exposure to show the spin. Pick the highest aperture number and lowest ISO number possible. If on an instant camera, try setting to landscape mode. If really desperate, put one or more sunglasses in front of the lens', '2007-03-28 16:20:21.000000', NULL, 1),
(3494507, 488344, 66341, '<td valign="top">Nice calming composition, though a lot of detail is lost in the shadows.</td>', 'Nice calming composition, though a lot of detail is lost in the shadows.', '2007-03-28 16:20:58.000000', NULL, 1),
(3494511, 489068, 66341, '<td valign="top">Nicely captured movement</td>', 'Nicely captured movement', '2007-03-28 16:21:35.000000', NULL, 1),
(3494513, 487206, 66341, '<td valign="top">seems to be a lot of camera shake</td>', 'seems to be a lot of camera shake', '2007-03-28 16:22:22.000000', NULL, 1),
