(3505659, 488204, 39623, '<td valign="top">It''s quite a blur. There should have been some identity. It could have passed of as an abstract, but it''s not even technically sound.</td>', 'It''s quite a blur. There should have been some identity. It could have passed of as an abstract, but it''s not even technically sound.', '2007-04-01 14:52:13.000000', NULL, 1),
(3505668, 489185, 39623, '<td valign="top">Well made prolonged exposure. Difficult to execute, but perfectly pulled off.<br/><br/><i>Message edited by author 2009-06-04 16:42:26.</i></td>', 'Well made prolonged exposure. Difficult to execute, but perfectly pulled off.', '2007-04-01 14:56:45.000000', '2009-06-04 17:42:26.000000', 1),
