(3506933, 489367, 1031, '<td valign="top">I like your idea of using the vase -- I''m thinking of an outdoor bouquet which wouldn''t need water ...</td>', 'I like your idea of using the vase -- I''m thinking of an outdoor bouquet which wouldn''t need water ...', '2007-04-01 19:42:52.000000', NULL, 1),
(3506940, 488801, 32872, '<td valign="top">I love your image!  Such a sweet look on her face and the beautiful green of the background keeps the focus upon her sweet smile, yet you still get the feeling of spinning! Great job. :) 10 from me.</td>', 'I love your image!  Such a sweet look on her face and the beautiful green of the background keeps the focus upon her sweet smile, yet you still get the feeling of spinning! Great job. :) 10 from me.', '2007-04-01 19:44:04.000000', NULL, 1),
