(3507196, 489429, 76389, '<td valign="top">The spinning light has a grace and fluidity that draw the eye to the center but the person holding the light remains invisible adding to the mystery of this picture. Although it is dimly lit, the warmth and the contrast in the background add to the sense of suspense.</td>', 'The spinning light has a grace and fluidity that draw the eye to the center but the person holding the light remains invisible adding to the mystery of this picture. Although it is dimly lit, the warmth and the contrast in the background add to the sense of suspense.', '2007-04-01 20:52:35.000000', NULL, 1),
(3507199, 489496, 50695, '<td valign="top">beautiful. cinematic. implies a sad story. within a Hitchcock movie. I believe this is the Posthumous Red Ribbon. 10</td>', 'beautiful. cinematic. implies a sad story. within a Hitchcock movie. I believe this is the Posthumous Red Ribbon. 10', '2007-04-01 20:53:00.000000', NULL, 1),
